SNB_st.name='SNB'; 
SNB_st.lat=47.0541;
SNB_st.lon=12.9577;
SNB_st.alt=3106;
SNB_st.env='Mt';
SNB_st.footp='Mx';
%%
SNB_rd=read_ebas_merged_STN('C:\github_trend\raw_data\merged_Sonnblick.nc', SNB_st); %[output:3e683cc6] %[output:832db609] %[output:67fee1c3] %[output:54033612] %[output:10fc3b59] %[output:2ea9f828] %[output:65b00e30] %[output:1a5ad459] %[output:36ed9233] %[output:017b43d2] %[output:28e1b070] %[output:381ca571] %[output:9fbb90c9] %[output:80a13647] %[output:839e5a60] %[output:68892e43] %[output:12cb5861] %[output:0982e724] %[output:0e7abfa6] %[output:44c7683a] %[output:71fc14d5] %[output:75fc2fab] %[output:60e70f4d] %[output:349cf81c] %[output:3171fd73] %[output:022029ce] %[output:7a437c30] %[output:4964eb84] %[output:01d3a0fc] %[output:040342e9] %[output:59db0187] %[output:856f921c] %[output:70b88910] %[output:15c993a9] %[output:03ab78fb] %[output:17506c8e] %[output:94289e0a] %[output:53bd94e8] %[output:6674ad70] %[output:6df4ca69] %[output:7715b5da] %[output:4f483e7e] %[output:674fd387] %[output:8f8a3680] %[output:22fc5fdb] %[output:63516763] %[output:66506052] %[output:104e825d] %[output:852c32a4] %[output:9f129a53] %[output:3821fc97] %[output:784ad96a] %[output:3de948c0] %[output:48867f51]
