SNB_rd.Properties.VariableNames{7}='Ba7_A';
names_rd=fieldnames(SNB_rd);
%[output:3ab2ad0d] %[output:51b54504] %[output:65aa6e0d] %[output:2ec14a87] %[output:1db74951] %[output:406bbe33] %[output:4e88371b] %[output:04a18664]
%%
datevec(SNB_rd.Time(1)) %data since 2016 %[output:8d5d9cf2]
datevec(SNB_rd.Time(end)) % 2025 %[output:4e34a620]
% % prctile(SNB_rd.U0_S11,[5 50 95]) % no RH given, but inlet heated to %[output:46ec2ebd]
% 20°C --> ok as at JFJ
% % prctile(SNB_rd.U1_S11,[5 50 95])
plotFigControl(SNB_rd,SNB_st.name);
%%
% BP detection for scat coef and backscat

names_sc={'BsB_S', 'BsG_S', 'BsR_S'};
break_SNB_scat_BP=change_point_analysis_Def(SNB_rd,names_sc,0.05,'SNB','scattering'); %[output:15b500f9] %[output:96081c03] %[output:2ac75d81] %[output:06c67983]
T_SNB_scat_BP=make_table_breakpoints_def(break_SNB_scat_BP);

names_bsc={'BbsB_S', 'BbsG_S', 'BbsR_S'};
break_SNB_bscat_BP=change_point_analysis_Def(SNB_rd,names_bsc,0.05,'SNB','Backscattering'); %[output:5caf2fb0] %[output:7014c4c4] %[output:86a64491] %[output:32c5c68e]
T_SNB_bscat_BP=make_table_breakpoints_def(break_SNB_bscat_BP);
%%
% BP detection for abs
names_abs={'Ba1_A', 'Ba2_A', 'Ba3_A','Ba4_A','Ba5_A','Ba6_A','Ba7_A'};
break_SNB_abs_BP=change_point_analysis_Def(SNB_rd,names_abs,0.05,'SNB','Absorption'); %[output:70a824b2] %[output:23f562e2] %[output:0cd05f1a] %[output:13eaeb69] %[output:92f94342] %[output:6bcc5326]
T_SNB_abs_BP=make_table_breakpoints_def(break_SNB_abs_BP);
%%
lambdaSC=[450;525;635];
lambdaAE=[370;470;520;590;660;880;950];
SNB_cal=compute_exp_SSA(SNB_rd,lambdaSC, lambdaAE); %[output:273d5cf0] %[output:6bd98dcf] %[output:8715f39b] %[output:1b04a7ae] %[output:889afe51] %[output:2b45292d] %[output:6ecac835] %[output:6a27d113] %[output:15aa69b4] %[output:3f15fa07] %[output:0adbed56] %[output:83a037dd] %[output:77d29ed7] %[output:016c1f61] %[output:5f9dc3cd] %[output:1f587c2b] %[output:67983922] %[output:00389e70] %[output:96776fc2] %[output:84f19b16] %[output:97173985] %[output:324d33b1] %[output:76e1af96] %[output:4a6bd08b] %[output:66b8142e] %[output:5a6c5618] %[output:1a3d4a7f] %[output:23229b0e] %[output:1ff41714] %[output:8dda1e6b] %[output:6ac01405] %[output:8b2e4eef] %[output:262392dd] %[output:367776d4] %[output:1b6676f8] %[output:41ccad47] %[output:45a8e055] %[output:1717fdb0] %[output:0f9f9841] %[output:53295033] %[output:9b670370] %[output:27afd3dd] %[output:60a31b91] %[output:32f7843b] %[output:71049a65] %[output:9d1b5897] %[output:8dc819c6] %[output:5b315e93] %[output:3ef601ea] %[output:69cb5581] %[output:121ddd0f]
plotFigControl_cal(SNB_cal,SNB_st.name); %[output:798bbc68] %[output:07998800] %[output:01b73702]
%%
% BP detection for expS, Backscat fraction, expA and SSA

names_exps={'expS_bg3', 'expS_br3', 'expS_gr3'};
break_SNB_exps_BP=change_point_analysis_Def(SNB_cal,names_exps,0.05,'SNB','scattering exp'); %[output:267db0e3] %[output:0e3cff04] %[output:0e92a826] %[output:8833b360]
T_SNB_exps_BP=make_table_breakpoints_def(break_SNB_exps_BP); %[output:19aca8ec] %[output:1c137a61] %[output:595aa50d] %[output:3e2e01e7]

names_BbF={'BbsFG'};
break_SNB_BbF_BP=change_point_analysis_Def(SNB_cal,names_BbF,0.05,'SNB','backscat fraction'); %[output:6a85448e] %[output:01485c8d]
T_SNB_BbF_BP=make_table_breakpoints_def(break_SNB_BbF_BP);

names_expA={'expA_fit'};
break_SNB_expA_BP=change_point_analysis_Def(SNB_cal,names_expA,0.05,'SNB','Absorption exp'); %[output:419ef90e] %[output:28c27d2a]
T_SNB_expA_BP=make_table_breakpoints_def(break_SNB_expA_BP);

names_SSA={'SSA311'};
break_SNB_SSA_BP=change_point_analysis_Def(SNB_cal,names_SSA,0.05,'SNB','SSA'); %[output:3162023c] %[output:6a1cbe27]
T_SNB_SSA_BP=make_table_breakpoints_def(break_SNB_SSA_BP);
%%
SNB_tr=SNB_rd;
SNB_tr.y=year(SNB_tr.Time);
SNB_tr=outerjoin(SNB_tr, SNB_cal);
%scat + backscat  trend on G  only:
SNB_tr.BsB_S=[];
SNB_tr.BsR_S=[];
SNB_tr.BbsB_S=[];
SNB_tr.BbsR_S=[];

% compute trend only on AE 520
SNB_tr.Ba1_A=[];
SNB_tr.Ba2_A=[];
SNB_tr.Ba4_A=[];
SNB_tr.Ba5_A=[];
SNB_tr.Ba6_A=[];
SNB_tr.Ba7_A=[];

%expS  trend on BG and expA fit from AE33 only:
SNB_tr.expS_br3=[];
SNB_tr.expS_gr3=[];
% compute only expA_fit
SNB_tr.expA_bg=[];
SNB_tr.expA_gr=[];
SNB_tr.expA_br=[];
%%
[SNB_result_MK,SNB_result_LMSlog,SNB_result_LMSlin]=all_trend_STN(SNB_tr,SNB_st); %[output:953645a8] %[output:6e19ab6e] %[output:78f7081b] %[output:6f9500bb] %[output:029a43f6] %[output:880455c8] %[output:8b877c97] %[output:32da3621] %[output:26a0582a] %[output:4ce19f4d] %[output:554655b0] %[output:891c78f0] %[output:9ed8bbe4] %[output:71f6ddf0] %[output:6838607c] %[output:05e93b32] %[output:1a6f35cc] %[output:8f43056b] %[output:87b1681f] %[output:5a9a7541] %[output:8737775b] %[output:4b64a01f] %[output:6b424dc8]

writetable(SNB_result_MK,'SNB_res_MK.txt'); %, 'delimiter',',' )
